#!/usr/bin/env python3
"""Install the current DRFT, DRT, and ESCRIB implementations into Spandrel.

The script is self-contained: its architecture sources and compatibility bootstrap are
stored in a compressed Base64 ZIP payload below. It uses only the Python standard library.

Typical chaiNNer usage on Windows:

    python patch_spandrel_drft.py

The installer targets the Spandrel package owned by the Python executable used
to launch it, with the standard chaiNNer AppData runtime as a fallback. Use
``--spandrel-root`` to target another environment explicitly.

Commands:

    patch_spandrel_drft.py install       Install or update DRFT, DRT, and ESCRIB (default).
    patch_spandrel_drft.py verify        Verify the installed payload.
    patch_spandrel_drft.py restore       Restore the newest unused backup.
    patch_spandrel_drft.py list-backups  List available backups.
"""

